changeSet.sql:
-- Create the sequence starting at 1
CREATE SEQUENCE IF NOT EXISTS audit_trail_seq START WITH 1;

-- Set the sequence to the next available value based on existing data
-- Use GREATEST(1, ...) to ensure we never try to set sequence to 0 (which is invalid)
SELECT setval('audit_trail_seq', 
    GREATEST(1,
        COALESCE(
            (SELECT MAX(
                CASE 
                    WHEN log_number ~ '^REQ[0-9]+$' 
                    THEN CAST(SUBSTRING(log_number FROM 4) AS BIGINT)
                    ELSE 0
                END
            ) FROM audit_trail), 
            0
        )
    ), 
    true
);
